if(!defined('ABSPATH'))exit;
/** TUFF BEATZ Project Activity Intelligence V12.15 — authoritative normalized project history */
function tuff_beatz_activity_type_map(){return array('message'=>array('label'=>'Message','group'=>'communication','priority'=>45),'file'=>array('label'=>'File Upload','group'=>'assets','priority'=>55),'delivery'=>array('label'=>'Delivery','group'=>'delivery','priority'=>90),'mastering'=>array('label'=>'Mastering','group'=>'production','priority'=>75),'review'=>array('label'=>'Review','group'=>'production','priority'=>70),'approval'=>array('label'=>'Approval','group'=>'production','priority'=>80),'workflow'=>array('label'=>'Workflow','group'=>'workflow','priority'=>65),'automation'=>array('label'=>'Automation','group'=>'workflow','priority'=>50),'milestone'=>array('label'=>'Milestone','group'=>'workflow','priority'=>55),'task'=>array('label'=>'Task','group'=>'workflow','priority'=>40),'timeline'=>array('label'=>'Timeline','group'=>'workflow','priority'=>35),'notification'=>array('label'=>'Notification','group'=>'communication','priority'=>30),'payment'=>array('label'=>'Payment','group'=>'commerce','priority'=>85),'invoice'=>array('label'=>'Invoice','group'=>'commerce','priority'=>70),'contract'=>array('label'=>'Contract','group'=>'commerce','priority'=>70),'quote'=>array('label'=>'Quote','group'=>'commerce','priority'=>60));}
function tuff_beatz_activity_normalize($item){$map=tuff_beatz_activity_type_map();$type=sanitize_key($item['type']??'update');$cfg=$map[$type]??array('label'=>ucwords(str_replace('-',' ',$type?:'Update')),'group'=>'project','priority'=>40);return array('id'=>(string)($item['id']??wp_generate_uuid4()),'type'=>$type?:'update','label'=>$cfg['label'],'group'=>$cfg['group'],'priority'=>(int)$cfg['priority'],'message'=>(string)($item['message']??'Project update'),'user_id'=>(int)($item['user_id']??0),'name'=>(string)($item['name']??'TUFF BEATZ'),'time'=>(string)($item['time']??''));}
function tuff_beatz_activity_history($id){$raw=function_exists('tuff_beatz_project_activity')?tuff_beatz_project_activity((int)$id):array();$out=array_map('tuff_beatz_activity_normalize',$raw);usort($out,function($a,$b){return strcmp($b['time'],$a['time']);});return $out;}
function tuff_beatz_activity_summary($id){$h=tuff_beatz_activity_history($id);$groups=array();$last='';$attention=0;foreach($h as $e){$groups[$e['group']]=($groups[$e['group']]??0)+1;if(!$last&&$e['time'])$last=$e['time'];if($e['priority']>=80)$attention++;}return array('total'=>count($h),'groups'=>$groups,'last_activity'=>$last,'high_value_events'=>$attention);}
function tuff_beatz_activity_workspace(){if(!is_page('project-dashboard')||!is_user_logged_in())return;$id=(int)($_GET['project']??0);if(!$id||!function_exists('tuff_beatz_user_can_view_request')||!tuff_beatz_user_can_view_request($id))return;$history=tuff_beatz_activity_history($id);$summary=tuff_beatz_activity_summary($id);?><script>document.addEventListener('DOMContentLoaded',function(){var timeline=document.getElementById('timeline');if(!timeline)return;var old=timeline.querySelector('.tb-activity');if(old)old.remove();var section=document.createElement('div');section.className='tb-activity-intelligence';section.innerHTML=<?php ob_start();?><div class="tb-ai-head"><div><small>PROJECT INTELLIGENCE V12.15</small><h3>Authoritative Activity History</h3></div><div class="tb-ai-stats"><span><strong><?php echo esc_html((string)$summary['total']);?></strong> EVENTS</span><span><strong><?php echo esc_html((string)$summary['high_value_events']);?></strong> KEY EVENTS</span></div></div><div class="tb-ai-filters"><button type="button" class="is-active" data-group="all">ALL</button><button type="button" data-group="communication">MESSAGES</button><button type="button" data-group="assets">FILES</button><button type="button" data-group="production">PRODUCTION</button><button type="button" data-group="workflow">WORKFLOW</button><button type="button" data-group="commerce">PAYMENTS</button><button type="button" data-group="delivery">DELIVERY</button></div><div class="tb-ai-stream"><?php if(!$history):?><p class="tb-empty-state">No project history yet.</p><?php else: foreach($history as $e):?><article class="tb-ai-event" data-group="<?php echo esc_attr($e['group']);?>"><i></i><div class="tb-ai-event-copy"><div><span class="tb-ai-event-type"><?php echo esc_html(strtoupper($e['label']));?></span><time><?php echo esc_html($e['time']?mysql2date('M j, Y • g:i a',$e['time']):''); ?></time></div><strong><?php echo esc_html($e['message']);?></strong><small><?php echo esc_html($e['name']);?></small></div></article><?php endforeach; endif;?></div><?php $html=ob_get_clean();echo wp_json_encode($html);?>;timeline.appendChild(section);section.querySelectorAll('.tb-ai-filters button').forEach(function(b){b.addEventListener('click',function(){section.querySelectorAll('.tb-ai-filters button').forEach(function(x){x.classList.remove('is-active')});b.classList.add('is-active');var g=b.dataset.group;section.querySelectorAll('.tb-ai-event').forEach(function(e){e.hidden=g!=='all'&&e.dataset.group!==g;});});});});</script><?php }
add_action('wp_footer','tuff_beatz_activity_workspace',29);
function tuff_beatz_activity_assets(){if(!is_page('project-dashboard'))return;wp_add_inline_style('tuff-beatz-milestones','.tb-activity-intelligence{margin-top:26px;padding-top:22px;border-top:1px solid rgba(255,255,255,.07)}.tb-ai-head{display:flex;justify-content:space-between;align-items:flex-end;gap:18px;margin-bottom:15px}.tb-ai-head small{color:#9a8b68;font-size:.58rem;letter-spacing:.16em}.tb-ai-head h3{margin:5px 0 0;color:#eee2c5;font-family:Cinzel,serif}.tb-ai-stats{display:flex;gap:8px}.tb-ai-stats span{padding:7px 9px;border:1px solid rgba(216,180,90,.14);border-radius:9px;color:#777064;font-size:.52rem;letter-spacing:.08em}.tb-ai-stats strong{color:#e5c66e}.tb-ai-filters{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:16px}.tb-ai-filters button{border:1px solid rgba(255,255,255,.07);border-radius:999px;background:transparent;color:#777166;padding:6px 9px;font-size:.54rem;letter-spacing:.08em;cursor:pointer}.tb-ai-filters button.is-active{border-color:rgba(216,180,90,.32);color:#e4c66f;background:rgba(216,180,90,.06)}.tb-ai-stream{display:grid;gap:0}.tb-ai-event{position:relative;display:grid;grid-template-columns:15px 1fr;gap:11px;padding:0 0 17px}.tb-ai-event:before{content:"";position:absolute;left:5px;top:10px;bottom:-2px;width:1px;background:rgba(255,255,255,.06)}.tb-ai-event:last-child:before{display:none}.tb-ai-event>i{width:11px;height:11px;margin-top:4px;border-radius:50%;border:2px solid #9e8240;background:#111}.tb-ai-event-copy>div{display:flex;justify-content:space-between;gap:10px}.tb-ai-event-type{color:#a98c48;font-size:.54rem;letter-spacing:.12em}.tb-ai-event time{color:#625e56;font-size:.56rem}.tb-ai-event-copy>strong{display:block;color:#d8d0c0;font-size:.72rem;margin:4px 0}.tb-ai-event-copy>small{color:#716c63;font-size:.58rem}@media(max-width:700px){.tb-ai-head{align-items:flex-start;flex-direction:column}.tb-ai-event-copy>div{flex-direction:column;gap:2px}}');}
add_action('wp_enqueue_scripts','tuff_beatz_activity_assets',98);
